begin;
do $$declare p uuid:=extensions.gen_random_uuid();o uuid:=extensions.gen_random_uuid();o2 uuid:=extensions.gen_random_uuid();who uuid;quote jsonb;pricing jsonb;inv text;cart jsonb;ship jsonb;qty integer;
begin
 select user_id into strict who from gac_private.owners limit 1;
 insert into public.gac_merch_products(id,name,price_cents,sizes,published,shipping_cents,tax_bps)values(p,'Synthetic guest checkout',100,array['S','M'],true,125,500);
 update public.gac_merch_stock set quantity=3 where product_id=p;
 update gac_private.merch_checkout_settings set enabled=true where singleton;
 cart:=jsonb_build_array(jsonb_build_object('id',p,'size','S','quantity',2,'unit_cents',1));ship:=jsonb_build_object('name','Test Customer','address1','123 Test St','address2','','city','Kathleen','state','GA','postal_code','00000','country','US','county','Houston','district','county');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
 quote:=public.gac_begin_merch_checkout(o,repeat('a',64),repeat('b',64),cart,ship,800);inv:=quote->>'invoice';if(quote->>'subtotal_cents')::int<>200 or(quote->>'shipping_cents')::int<>250 or(quote->>'tax_cents')::int<>36 or(quote->>'tax_rate_bps')::int<>800 or(quote->>'total_cents')::int<>486 then raise exception 'Product pricing was not used for the quote';end if;
 perform public.gac_begin_merch_checkout(o,repeat('a',64),repeat('b',64),cart,ship,800);
 begin perform public.gac_begin_merch_checkout(o2,repeat('c',64),repeat('d',64),cart,ship,800);raise exception 'Reserved stock oversold';exception when raise_exception then if position('Not enough stock'in sqlerrm)=0 then raise;end if;end;
 reset role;if gac_private.merch_available(p,'S')<>1 then raise exception 'Reservation not reflected';end if;
 perform set_config('request.jwt.claim.sub',who::text,true);set local role authenticated;
 begin perform public.gac_owner_change_merch_stock(p,'S','count',1,0,'Reserved count reduction',extensions.gen_random_uuid());raise exception 'Reserved stock manually removed';exception when raise_exception then if position('Stock is reserved'in sqlerrm)=0 then raise;end if;end;
 pricing:=public.gac_owner_merch_checkout_settings(895,725);if pricing->>'shipping_cents'<>'895'or pricing->>'tax_bps'<>'725'or pricing->>'enabled'<>'false' then raise exception 'Manual pricing unexpectedly enabled checkout';end if;
 begin perform public.gac_owner_merch_checkout(true);raise exception 'Owner enabled paid checkout before release';exception when raise_exception then if position('remains disabled'in sqlerrm)=0 then raise;end if;end;
 reset role;update gac_private.merch_checkout_settings set enabled=true where singleton;set local role service_role;
 begin perform public.gac_merch_order_session(o,repeat('c',64));raise exception 'Order access bypass';exception when no_data_found then null;end;
 if public.gac_apply_merch_gateway('98767001',inv,null,'authCaptureTransaction','capturedPendingSettlement',485,now(),true,'test@example.invalid','{"address1":"123 Test St","postal_code":"00000"}')<>'review'then raise exception 'Amount mismatch fulfilled';end if;
 if public.gac_apply_merch_gateway('98767001',inv,null,'authCaptureTransaction','FDSAuthorizedPendingReview',486,now(),false,null,'{}')<>'protected'then raise exception 'Review not protected';end if;
 if public.gac_apply_merch_gateway('98767001',inv,null,'authCaptureTransaction','capturedPendingSettlement',486,now(),true,'test@example.invalid',ship)<>'credited'then raise exception 'Approval not fulfilled';end if;
 perform public.gac_apply_merch_gateway('98767001',inv,null,'authCaptureTransaction','capturedPendingSettlement',486,now(),true,'test@example.invalid',ship);reset role;
 if(select quantity from public.gac_merch_stock where product_id=p and size='S')<>1 or(select quantity from public.gac_merch_stock where product_id=p and size='M')<>3 then raise exception 'Wrong stock deduction';end if;
 if(select count(*)from gac_private.merch_stock_events where order_id=o)<>1 then raise exception 'Duplicate fulfillment ledger';end if;
 if(select count(*)from public.gac_store_orders where order_number=inv and user_id is null and fulfillment_status='pending_fulfillment' and shipping_address->>'county'='Houston' and shipping_address->>'tax_rate_bps'='800')<>1 then raise exception 'Paid guest order or tax destination was not recorded';end if;
 set local role service_role;perform public.gac_apply_merch_gateway('98767002',inv,'98767001','refundTransaction','refundSettledSuccessfully',100,now(),true,null,'{}');reset role;
 if(select state from gac_private.merch_orders where id=o)<>'partially_refunded'or(select quantity from public.gac_merch_stock where product_id=p and size='S')<>1 then raise exception 'Partial refund restocked or mislabeled';end if;
 set local role service_role;perform public.gac_apply_merch_gateway('98767003',inv,'98767001','refundTransaction','refundSettledSuccessfully',386,now(),true,null,'{}');reset role;
 if(select state from gac_private.merch_orders where id=o)<>'refunded'then raise exception 'Full refund not recorded';end if;
 if has_function_privilege('anon','public.gac_begin_merch_checkout(uuid,text,text,jsonb,jsonb,integer)','execute')or has_function_privilege('anon','public.gac_merch_checkout_available()','execute')or has_table_privilege('authenticated','gac_private.merch_orders','select')then raise exception 'Order privacy or service write gate missing';end if;
end $$;
rollback;
